public int largestMagicSquare(int[][] grid) {
    int row = grid.length;
    int col = grid[0].length;
    int maxSize = 1;

    for(int i = 0; i < row; i++){
        for(int j = 0; j < col; j++){
            for(int k = 2; k + i <= row && k + j <= col; k++){
                if(k > maxSize && isMagic(grid, i, j, k)){
                    maxSize = Math.max(maxSize, k);
                }
            }
        }
    }
    return maxSize;
}
